import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"4、【蒙】 坎下艮上","description":"周易口诀义 - 4、【蒙】 坎下艮上","frontmatter":{"title":"4、【蒙】 坎下艮上","description":"周易口诀义 - 4、【蒙】 坎下艮上"},"headers":[],"relativePath":"zh/classics/koujueyi/006.md","filePath":"zh/classics/koujueyi/006.md"}'),r={name:"zh/classics/koujueyi/006.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_4、【蒙】-坎下艮上" tabindex="-1">4、【蒙】 坎下艮上 <a class="header-anchor" href="#_4、【蒙】-坎下艮上" aria-label="Permalink to “4、【蒙】 坎下艮上”">​</a></h1><p>彖曰：「蒙」，山下有险，险而止，蒙。「蒙亨」，以亨行时中也。「匪我求童蒙，童蒙求我」，志应也。「初筮告」，以刚中也。「再三渎，渎则不告」，渎蒙也。蒙以养正，圣功也。</p><p>象曰：山下出泉，「蒙」，君子以果行育德。</p><p>初六：发蒙，利用刑人，用说桎梏，以往，吝。</p><p>象曰：「利用刑人」，以正法也。</p><p>九二：包蒙，吉。纳妇吉。子克家。</p><p>象曰：「子克家」，刚柔接也。</p><p>六三：勿用取女，见金夫，不有躬，无攸利。</p><p>象曰：「勿用取女」，行不顺也。</p><p>六四，困蒙，吝。</p><p>象曰：「困蒙」之吝，独远实也。</p><p>六五，童蒙吉。</p><p>象曰：「童蒙」之吉，顺以巽也。</p><p>上九，击蒙，不利为寇，利御冠。</p><p>象曰：利用「御寇」，上下顺也。</p><p>解读</p><p>「蒙亨」者，蒙者童稚之名，暗昧之义。处「童蒙」之时，所愿获通，故曰「蒙亨」。「匪我求童蒙，童蒙求我」者，匪，非也，「童蒙」者谓五也，「我」谓二也。五处「童蒙」之时，当求九二之明师也。「再三渎，渎则不告」者，渎，乱也，蒙昧之人，心多疑惑，若明师与之决蒙，须一理而说，使其晓悟。若其广说引谕至于繁多，即蒙者渎乱，乱即还同不告。「利贞」者，蒙而未晓，心须养正乃通，至圣之功也。</p><p>象曰「山下出泉，蒙，君子以果行育德」者，王氏云：「山下出泉，未知所适，蒙之象也。」君子处是时而未获通，当须果决为行，育养己德，德立道成，可以适蒙之险。</p><p>「初六，发蒙，利用刑人，用说桎梏，以往吝」者，初六虽是暗昧，而与九二相近，即是亲比明师，以去蒙暗。蒙既显发，即心无凝滞，乃能利用刑罚罪人，又能脱去罪人桎梏之象，言其明于法律，举事合宜。凡刑罚之道，不可常行，鞭扑不可弛之家，刑罚不可弛之国。若用刑不已，民所不堪，即有悔吝之道，故曰「以往吝」。尔雅云：「杽谓之桎，械谓之梏也。」</p><p>「九二，包蒙，吉。纳妇吉，子克家」者，凡言「妇」者，配己成德。九二刚阳之德而居中，群阴悉来，物来归己，而能纳之，故曰「包蒙吉」也。心既弘通，不拒于物，即配德者归焉，故曰「纳妇吉」也。刚而处中，纳此匹配，是能干济家事，施之子孙，而能克荷家事，故曰「子克家」也。</p><p>「六三，勿用取女，见金夫，不有躬，无攸利」者，「蒙」之为体，阴先求阳，弱先求强。六三是阴柔，即是先求上九者也。喻之人事，是女先求于男也。女以婉顺为德，待礼而行，今既先求于男，故不可取也。「见金夫，不有躬，无攸利」者，金，刚也。上九刚夫而乃往就之，是无闺阁之德，故不可取之而无所利也。六四「困蒙，吝」者，既不近明师，无人显发其暗，深可鄙也。「六五童蒙，吉」者，柔而处尊，不自任察，但委付于二，不劳己之聪明，犹如童稚之人，自可获吉，如成王委用周公之义。</p><p>上九：击蒙，不利为寇。「利御寇」者，上九阳明之德，处众阴之上，能于众阴击去蒙暗，故曰「击蒙」也。众阴亲托，皆愿求安，能为群阴去除寇难，则荷戴弥深。若因人之隙，便生苟且而以取之，则众阴叛矣，故云不利为寇而利用御寇也。</p>',22)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
